public enum HunkType: Equatable, Hashable {
    
    case added
    case removed
    case modified





}

#if compiler(>=6)
extension HunkType: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeHunkType: FfiConverterRustBuffer {
    typealias SwiftType = HunkType

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> HunkType {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .added
        
        case 2: return .removed
        
        case 3: return .modified
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: HunkType, into buf: inout [UInt8]) {
        switch value {
        
        
        case .added:
            writeInt(&buf, Int32(1))
        
        
        case .removed:
            writeInt(&buf, Int32(2))
        
        
        case .modified:
            writeInt(&buf, Int32(3))
        
        }
    }
}


