public struct FfiConverterTypeJayJayError: FfiConverterRustBuffer {
    typealias SwiftType = JayJayError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> JayJayError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .RepoNotFound(
            path: try FfiConverterString.read(from: &buf)
            )
        case 2: return .RevNotFound(
            rev: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Internal(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: JayJayError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .RepoNotFound(path):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(path, into: &buf)
            
        
        case let .RevNotFound(rev):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(rev, into: &buf)
            
        
        case let .Internal(message):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


